CREATE TABLE IF NOT EXISTS "customers_table" ("id" TEXT NOT NULL, "business_id" TEXT NOT NULL REFERENCES businesses_table (id) ON DELETE CASCADE, "external_id" TEXT NULL, "external_source" TEXT NULL, "name" TEXT NOT NULL, "email" TEXT NULL, "phone" TEXT NULL, "address" TEXT NULL, "city" TEXT NULL, "country" TEXT NULL, "segments" TEXT NULL, "lifetime_value" REAL NULL, "order_count" INTEGER NULL, "total_spent" REAL NULL, "avg_order_value" REAL NULL, "last_order_date" INTEGER NULL, "churn_risk" REAL NULL, "created_at" INTEGER NOT NULL DEFAULT 1784865953, "updated_at" INTEGER NOT NULL DEFAULT 1784865953, "domain_snapshot" TEXT NULL, PRIMARY KEY ("id"));
CREATE INDEX customers_business_id ON customers_table (business_id);
